package com.cpf.batch.agent.internal; import com.cpf.batch.agent.AgentProperties; import org.springframework.web.client.RestClient;
public final class RuntimeControlProxy { private final AgentProperties p;private final RestClient.Builder b;public RuntimeControlProxy(AgentProperties p,RestClient.Builder b){this.p=p;this.b=b;} public void invoke(String id,String op){var s=p.getServices().values().stream().filter(x->id.equals(x.getServiceId())).findFirst().orElseThrow(()->new SecurityException("unknown service"));String base=s.getRuntimeControlUrl();if(base==null||base.isBlank())throw new IllegalStateException("runtime control endpoint is not configured for "+id);if(!base.matches("https?://(127\\.0\\.0\\.1|localhost):\\d+.*"))throw new SecurityException("runtime control must be loopback");b.baseUrl(base).build().post().uri("/"+op).retrieve().toBodilessEntity();} }
